199: // wait follows the run until the grant settles, pauses, parks or goes stale.
200: // A daemon that disappears is started again and followed from its store.
201: func (d *Daemon) wait(ctx context.Context, round Round, grant string) (RoundResult, error) {
202: 	deadline := time.Now().Add(round.Wait)
203: 	stream, sequence := "", uint64(0)
204: 	for {
205: 		v, err := d.attach(ctx, round)
206: 		if errors.Is(err, errUnavailable) {
207: 			if _, err := d.Ensure(ctx); err != nil {
208: 				return RoundResult{}, err
209: 			}
210: 			continue
211: 		}
212: 		if err != nil {
213: 			return RoundResult{}, err
214: 		}
215: 		result := RoundResult{Grant: grant, RunID: v.RunID, Result: v.HostResult}
216: 		if v.Run != nil && v.Run.Recovery != nil {
217: 			result.Outcome, result.Recovery = RecoveryRequired, v.Run.Recovery
218: 			return result, nil
219: 		}
220: 		if hr := v.HostResult; hr != nil && hr.Grant == grant {
221: 			switch {
222: 			case !hr.Current && hr.Status == "running":
223: 				// Greenhouse refuses a successor while the stale review runs. A
224: 				// refused cancel means the review settled meanwhile.
225: 				request, _ := json.Marshal(d.request(round, v, grant, "cancel", nil))
226: 				if _, err := d.axi(ctx, round.Worktree, request); err != nil && !errors.Is(err, errUnavailable) {
227: 					return RoundResult{}, err
228: 				}
229: 				continue
230: 			case !hr.Current && hr.Status == "cancelling":
231: 			case !hr.Current:
232: 				result.Outcome = Stale
233: 				return result, nil
234: 			case hr.Verdict != "":
235: 				result.Outcome = Settled
236: 				return result, nil
237: 			case hr.Status == "paused":
238: 				result.Outcome = Paused
239: 				return result, nil
240: 			}
241: 		}
242: 		remaining := time.Until(deadline)
243: 		if remaining <= 0 {
244: 			result.Outcome = Running
245: 			return result, nil
246: 		}
247: 		if stream == "" {
248: 			stream, sequence = v.Stream, v.Sequence
249: 		}
250: 		wait := min(remaining, 2*time.Second)
251: 		request, _ := json.Marshal(map[string]any{"version": Protocol, "op": "watch", "stream": stream, "after": sequence, "wait_ms": wait.Milliseconds()})
252: 		watched, err := d.axi(ctx, round.Worktree, request)
253: 		if err != nil || watched.Stream == "" {
254: 			time.Sleep(100 * time.Millisecond)
255: 			stream = ""
256: 			continue
257: 		}
258: 		stream, sequence = watched.Stream, watched.Sequence
259: 	}
260: }
