	}
	sandboxes := homeSandboxes(ctx, db)
	if cwd, err := os.Getwd(); err == nil && insideAny(cwd, sandboxes) {
		return true
	}
	for _, process := range ancestors {
		if process.cwd != "" && insideAny(process.cwd, sandboxes) {
			return true
		}
	}
	return false
}

