+func (c *greenhouseContract) hostGrants(t *testing.T) []any {
+	t.Helper()
+	inspected := c.greenhouse(t, map[string]any{"version": 2, "op": "inspect"})
+	run, _ := inspected["run"].(map[string]any)
+	grants, _ := run["host_grants"].([]any)
+	return grants
+}
