+package greenhouse
+
+import (
+	"slices"
+	"testing"
+)
+
+func TestDaemonEnvironmentDropsTaskAndPaneIdentity(t *testing.T) {
+	d := Daemon{Home: "/posse/greenhouse", Env: []string{"PATH=/bin", "POSSE_TASK_ID=marker", "POSSE_HOME=/posse", "HERDR_PANE_ID=p1", "GREENHOUSE_HOME=/user/greenhouse", "GIT_DIR=/repo/.git", "PI_CODING_AGENT_DIR=/agent"}}
+	got := d.environment()
+	want := []string{"PATH=/bin", "PI_CODING_AGENT_DIR=/agent", "GREENHOUSE_HOME=/posse/greenhouse"}
+	if !slices.Equal(got, want) {
+		t.Fatalf("environment() = %v, want %v", got, want)
+	}
+}
+
+func TestProtocolErrorNamesBothRanges(t *testing.T) {
+	err := (&ProtocolError{Daemon: Range{Min: 1, Max: 1}}).Error()
+	if want := "the Greenhouse daemon speaks protocol 1 and Posse needs protocol 2"; err[:len(want)] != want {
+		t.Fatalf("ProtocolError = %q", err)
+	}
+	if (Range{Min: 1, Max: 2}).String() != "1-2" || !(Range{Min: 1, Max: 2}).Includes(Protocol) || (Range{Min: 1, Max: 1}).Includes(Protocol) {
+		t.Fatal("Range comparison is wrong")
+	}
+}
diff --git a/internal/greenhouse/protocol.go b/internal/greenhouse/protocol.go
new file mode 100644
index 0000000..105d02f
--- /dev/null
+++ b/internal/greenhouse/protocol.go
@@ -0,0 +1,159 @@
+// Package greenhouse is Posse's host adapter for Greenhouse review in host mode.
+// It speaks AXI protocol version 2 to `greenhouse axi`, one request per
+// invocation, against a daemon that Posse starts and places itself.
+package greenhouse
+
+import (
+	"bytes"
+	"context"
+	"encoding/json"
+	"errors"
+	"fmt"
+	"os/exec"
+	"strings"
+)
+
+// Protocol is the only AXI envelope version the adapter speaks. It never
+// downgrades: host mode does not exist below version 2.
+const Protocol = 2
+
+// Range is an inclusive protocol version range.
+type Range struct {
+	Min int `json:"min"`
+	Max int `json:"max"`
+}
+
+func (r Range) Includes(version int) bool { return r.Min <= version && version <= r.Max }
+
+func (r Range) String() string {
+	if r.Min == r.Max {
+		return fmt.Sprint(r.Min)
+	}
+	return fmt.Sprintf("%d-%d", r.Min, r.Max)
+}
+
+// PosseRange is the protocol range this adapter accepts.
+var PosseRange = Range{Min: Protocol, Max: Protocol}
+
+// ProtocolError refuses a daemon whose range excludes the adapter's version.
+type ProtocolError struct {
+	Daemon Range
+}
+
+func (e *ProtocolError) Error() string {
+	return fmt.Sprintf("the Greenhouse daemon speaks protocol %s and Posse needs protocol %s; Posse does not downgrade. Let its work settle, stop it and install a Greenhouse that speaks protocol %d", e.Daemon, PosseRange, Protocol)
+}
+
+// Host identifies the Posse host run, one per Task Member.
+type Host struct {
+	Name string `json:"name"`
+	ID   string `json:"id"`
+}
+
+// Finding is one Greenhouse finding as host_result reports it.
+type Finding struct {
+	ID          string `json:"id"`
+	Priority    string `json:"priority"`
+	Origin      string `json:"origin"`
+	File        string `json:"file"`
+	Start       int    `json:"start"`
+	End         int    `json:"end"`
+	Explanation string `json:"explanation"`
+	Action      string `json:"action"`
+	Rule        string `json:"rule"`
+	Head        string `json:"head"`
+}
+
+// HostResult is the exact-head review result of a host run.
+type HostResult struct {
+	Grant        string    `json:"grant"`
+	ReviewID     string    `json:"review_id"`
+	Head         string    `json:"head"`
+	Target       string    `json:"target"`
+	ReviewBase   string    `json:"review_base"`
+	Status       string    `json:"status"`
+	Verdict      string    `json:"verdict"`
+	Current      bool      `json:"current"`
+	Findings     []Finding `json:"findings"`
+	RulesDigest  string    `json:"rules_digest"`
+	ConfigDigest string    `json:"config_digest"`
+	InputDigest  string    `json:"input_digest"`
+	Backend      string    `json:"backend"`
+	Model        string    `json:"model"`
+	Reason       string    `json:"reason"`
+}
+
+// Recovery is set while a run waits for recovery after an interruption.
+type Recovery struct {
+	ID      string   `json:"id"`
+	Reason  string   `json:"reason"`
+	Options []string `json:"options"`
+}
+
+type run struct {
+	ID         string    `json:"id"`
+	Status     string    `json:"status"`
+	Candidate  string    `json:"candidate"`
+	HostGrants []string  `json:"host_grants"`
+	ReviewUsed int       `json:"review_used"`
+	Recovery   *Recovery `json:"recovery"`
+}
+
+type defaults struct {
+	Rules           []string `json:"rules"`
+	ReviewerBackend string   `json:"reviewer_backend"`
+	ReviewerModel   string   `json:"reviewer_model"`
+}
+
+type response struct {
+	Version    int         `json:"version"`
+	Outcome    string      `json:"outcome"`
+	Error      string      `json:"error"`
+	RunID      string      `json:"run_id"`
+	InputID    string      `json:"input_id"`
+	GateID     string      `json:"gate_id"`
+	Token      string      `json:"token"`
+	RulesReady bool        `json:"rules_ready"`
+	Run        *run        `json:"run"`
+	Defaults   *defaults   `json:"defaults"`
+	HostResult *HostResult `json:"host_result"`
+	Protocol   *Range      `json:"protocol"`
+	Stream     string      `json:"stream"`
+	Sequence   uint64      `json:"sequence"`
+}
+
+func (v response) refusal(op string) error {
+	if v.Outcome == "ok" {
+		return nil
+	}
+	if v.Protocol != nil && !v.Protocol.Includes(Protocol) {
+		return &ProtocolError{Daemon: *v.Protocol}
+	}
+	return fmt.Errorf("greenhouse %s %s: %s", op, v.Outcome, v.Error)
+}
+
+var errUnavailable = errors.New("greenhouse daemon unavailable")
+
+func (d *Daemon) axi(ctx context.Context, dir string, request []byte) (response, error) {
+	command := exec.CommandContext(ctx, d.Binary, "axi")
+	command.Dir = dir
+	command.Env = d.environment()
+	command.Stdin = bytes.NewReader(request)
+	var stdout, stderr bytes.Buffer
+	command.Stdout, command.Stderr = &stdout, &stderr
+	runErr := command.Run()
+	var v response
+	if err := json.Unmarshal(stdout.Bytes(), &v); err != nil {
+		if runErr != nil {
+			return v, fmt.Errorf("greenhouse axi: %w: %s", runErr, strings.TrimSpace(stderr.String()))
+		}
+		return v, fmt.Errorf("greenhouse axi returned no envelope: %w", err)
+	}
+	if v.Outcome == "error" && strings.Contains(v.Error, "daemon unavailable") {
+		return v, fmt.Errorf("%w: %s", errUnavailable, v.Error)
+	}
+	if v.Outcome == "error" {
+		return v, fmt.Errorf("greenhouse axi error: %s", v.Error)
+	}
+	return v, nil
+}
diff --git a/internal/greenhouse/round.go b/internal/greenhouse/round.go
new file mode 100644
index 0000000..9f5121f
--- /dev/null
+++ b/internal/greenhouse/round.go
@@ -0,0 +1,318 @@
+package greenhouse
+
+import (
+	"context"
+	"encoding/json"
+	"errors"
+	"fmt"
+	"os"
+	"os/exec"
+	"strings"
+	"time"
+
+	"github.com/thanhbinh1905/posse/internal/atomicfile"
+)
+
+// Settings selects the rules and reviewer passed to Greenhouse `apply`. Empty
+// fields take the daemon's defaults.
+type Settings struct {
+	Rules           []string
+	ReviewerBackend string
+	ReviewerModel   string
+}
+
+// Round asks Greenhouse for one exact-head review of a Task Member.
+type Round struct {
+	Worktree string
+	Host     Host
+	// GrantPrefix is "<project>/t<seq>/<member>"; round n uses GrantPrefix/r<n>.
+	GrantPrefix string
+	Intent      string
+	Target      string
+	Settings    Settings
+	// Pending is the write-ahead record of the review request in flight, so a
+	// restarted Posse replays the same request instead of spending a new grant.
+	Pending string
+	Wait    time.Duration
+	// Checkpoint, when set, runs at named steps so tests can stop Posse there.
+	Checkpoint func(step string)
+}
+
+type Outcome string
+
+const (
+	// Settled: the grant has a verdict; Result.Current says whether it still binds the head.
+	Settled Outcome = "settled"
+	// Stale: the head moved, so the result binds no head.
+	Stale Outcome = "stale"
+	// Paused: a backend pause; the same grant resumes later.
+	Paused Outcome = "paused"
+	// RecoveryRequired: the run parked after an interruption; no new grant until it is resolved.
+	RecoveryRequired Outcome = "recovery-required"
+	// Running: the wait ended before the review settled.
+	Running Outcome = "running"
+)
+
+type RoundResult struct {
+	Outcome  Outcome
+	Grant    string
+	RunID    string
+	Result   *HostResult
+	Recovery *Recovery
+	// Replayed is true when the review request was replayed for its receipt.
+	Replayed bool
+}
+
+type pendingReview struct {
+	Grant   string          `json:"grant"`
+	Request json.RawMessage `json:"request"`
+}
+
+// Review continues the Member's round in flight, or starts the next one.
+func (d *Daemon) Review(ctx context.Context, round Round) (RoundResult, error) {
+	if _, err := d.Ensure(ctx); err != nil {
+		return RoundResult{}, err
+	}
+	v, err := d.attach(ctx, round)
+	if err != nil {
+		return RoundResult{}, err
+	}
+	pending, err := readPending(round.Pending)
+	if err != nil {
+		return RoundResult{}, err
+	}
+	if v.Run != nil && v.Run.Recovery != nil {
+		grant := ""
+		if pending != nil {
+			grant = pending.Grant
+		}
+		return RoundResult{Outcome: RecoveryRequired, Grant: grant, RunID: v.RunID, Recovery: v.Run.Recovery}, nil
+	}
+	if pending != nil {
+		return d.continueReview(ctx, round, v, *pending)
+	}
+	return d.startReview(ctx, round, v)
+}
+
+// ClearPending ends the round in flight once Posse has acted on its result.
+func ClearPending(path string) error {
+	if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
+		return err
+	}
+	return nil
+}
+
+func (d *Daemon) continueReview(ctx context.Context, round Round, v response, pending pendingReview) (RoundResult, error) {
+	delivered := v.HostResult != nil && v.HostResult.Grant == pending.Grant
+	replay, err := d.axi(ctx, round.Worktree, pending.Request)
+	if err != nil {
+		return RoundResult{}, err
+	}
+	if replay.Outcome != "ok" && !delivered {
+		// The request never reached the daemon and its envelope is stale.
+		if err := ClearPending(round.Pending); err != nil {
+			return RoundResult{}, err
+		}
+		return d.startReview(ctx, round, v)
+	}
+	if delivered && v.HostResult.Status == "paused" {
+		if _, err := d.call(ctx, round, v, pending.Grant, "resume", nil); err != nil {
+			return RoundResult{}, err
+		}
+	}
+	result, err := d.wait(ctx, round, pending.Grant)
+	result.Replayed = delivered && replay.Outcome == "ok"
+	return result, err
+}
+
+func (d *Daemon) startReview(ctx context.Context, round Round, v response) (RoundResult, error) {
+	used := 0
+	if v.Run != nil {
+		used = len(v.Run.HostGrants)
+	}
+	grant := fmt.Sprintf("%s/r%d", round.GrantPrefix, used+1)
+	head, err := worktreeHead(ctx, round.Worktree)
+	if err != nil {
+		return RoundResult{}, err
+	}
+	if v.HostResult != nil || v.Run == nil || v.Run.Candidate != head {
+		if v, err = d.call(ctx, round, v, grant, "new", nil); err != nil {
+			return RoundResult{}, err
+		}
+	}
+	selected := round.Settings
+	if v.Defaults != nil {
+		if len(selected.Rules) == 0 {
+			selected.Rules = v.Defaults.Rules
+		}
+		if selected.ReviewerBackend == "" {
+			selected.ReviewerBackend, selected.ReviewerModel = v.Defaults.ReviewerBackend, v.Defaults.ReviewerModel
+		}
+	}
+	// Host mode ignores the limit, but apply refuses one below consumed usage.
+	limit := 1
+	if v.Run != nil {
+		limit += v.Run.ReviewUsed
+	}
+	settings := map[string]any{
+		"mode": "ask", "preset": "one-pass", "limit": limit, "rules": selected.Rules,
+		"reviewer_backend": selected.ReviewerBackend, "reviewer_model": selected.ReviewerModel,
+		"fixer_backend": selected.ReviewerBackend, "fixer_model": selected.ReviewerModel,
+	}
+	if v, err = d.call(ctx, round, v, grant, "apply", map[string]any{"settings": settings}); err != nil {
+		return RoundResult{}, err
+	}
+	if v, err = d.call(ctx, round, v, grant, "resolve-rules", nil); err != nil {
+		return RoundResult{}, err
+	}
+	if !v.RulesReady {
+		return RoundResult{}, fmt.Errorf("greenhouse rules %v did not load", selected.Rules)
+	}
+	if v, err = d.call(ctx, round, v, grant, "prepare", map[string]any{"intent": round.Intent, "target": round.Target}); err != nil {
+		return RoundResult{}, err
+	}
+	request, err := json.Marshal(d.request(round, v, grant, "review", map[string]any{"grant": grant}))
+	if err != nil {
+		return RoundResult{}, err
+	}
+	record, err := json.Marshal(pendingReview{Grant: grant, Request: request})
+	if err != nil {
+		return RoundResult{}, err
+	}
+	if err := atomicfile.Write(round.Pending, record, 0o600); err != nil {
+		return RoundResult{}, err
+	}
+	reviewed, err := d.axi(ctx, round.Worktree, request)
+	if err != nil {
+		return RoundResult{}, err
+	}
+	if err := reviewed.refusal("review"); err != nil {
+		_ = ClearPending(round.Pending)
+		return RoundResult{}, err
+	}
+	if round.Checkpoint != nil {
+		round.Checkpoint("review-sent")
+	}
+	return d.wait(ctx, round, grant)
+}
+
+// wait follows the run until the grant settles, pauses, parks or goes stale.
+// A daemon that disappears is started again and followed from its store.
+func (d *Daemon) wait(ctx context.Context, round Round, grant string) (RoundResult, error) {
+	deadline := time.Now().Add(round.Wait)
+	stream, sequence := "", uint64(0)
+	for {
+		v, err := d.attach(ctx, round)
+		if errors.Is(err, errUnavailable) {
+			if _, err := d.Ensure(ctx); err != nil {
+				return RoundResult{}, err
+			}
+			continue
+		}
+		if err != nil {
+			return RoundResult{}, err
+		}
+		result := RoundResult{Grant: grant, RunID: v.RunID, Result: v.HostResult}
+		if v.Run != nil && v.Run.Recovery != nil {
+			result.Outcome, result.Recovery = RecoveryRequired, v.Run.Recovery
+			return result, nil
+		}
+		if hr := v.HostResult; hr != nil && hr.Grant == grant {
+			switch {
+			case !hr.Current && hr.Status == "running":
+				// Greenhouse refuses a successor while the stale review runs. A
+				// refused cancel means the review settled meanwhile.
+				request, _ := json.Marshal(d.request(round, v, grant, "cancel", nil))
+				if _, err := d.axi(ctx, round.Worktree, request); err != nil && !errors.Is(err, errUnavailable) {
+					return RoundResult{}, err
+				}
+				continue
+			case !hr.Current && hr.Status == "cancelling":
+			case !hr.Current:
+				result.Outcome = Stale
+				return result, nil
+			case hr.Verdict != "":
+				result.Outcome = Settled
+				return result, nil
+			case hr.Status == "paused":
+				result.Outcome = Paused
+				return result, nil
+			}
+		}
+		remaining := time.Until(deadline)
+		if remaining <= 0 {
+			result.Outcome = Running
+			return result, nil
+		}
+		if stream == "" {
+			stream, sequence = v.Stream, v.Sequence
+		}
+		wait := min(remaining, 2*time.Second)
+		request, _ := json.Marshal(map[string]any{"version": Protocol, "op": "watch", "stream": stream, "after": sequence, "wait_ms": wait.Milliseconds()})
+		watched, err := d.axi(ctx, round.Worktree, request)
+		if err != nil || watched.Stream == "" {
+			time.Sleep(100 * time.Millisecond)
+			stream = ""
+			continue
+		}
+		stream, sequence = watched.Stream, watched.Sequence
+	}
+}
+
+func (d *Daemon) attach(ctx context.Context, round Round) (response, error) {
+	request, _ := json.Marshal(map[string]any{"version": Protocol, "op": "attach", "host": round.Host})
+	v, err := d.axi(ctx, round.Worktree, request)
+	if err != nil {
+		return v, err
+	}
+	return v, v.refusal("attach")
+}
+
+// call sends one host mutation. Its action ID names the grant, the operation
+// and the run token it expects, so an identical retry replays its receipt.
+func (d *Daemon) call(ctx context.Context, round Round, v response, grant, op string, extra map[string]any) (response, error) {
+	request, err := json.Marshal(d.request(round, v, grant, op, extra))
+	if err != nil {
+		return v, err
+	}
+	next, err := d.axi(ctx, round.Worktree, request)
+	if err != nil {
+		return next, err
+	}
+	return next, next.refusal(op)
+}
+
+func (d *Daemon) request(round Round, v response, grant, op string, extra map[string]any) map[string]any {
+	q := map[string]any{
+		"version": Protocol, "op": op, "host": round.Host,
+		"run_id": v.RunID, "input_id": v.InputID, "gate_id": v.GateID, "expected": v.Token,
+		"action_id": grant + "/" + op + "/" + v.Token, "reason": "Posse host review " + grant,
+	}
+	for key, value := range extra {
+		q[key] = value
+	}
+	return q
+}
+
+func readPending(path string) (*pendingReview, error) {
+	data, err := os.ReadFile(path)
+	if errors.Is(err, os.ErrNotExist) {
+		return nil, nil
+	}
+	if err != nil {
+		return nil, err
+	}
+	var pending pendingReview
+	if err := json.Unmarshal(data, &pending); err != nil || pending.Grant == "" || len(pending.Request) == 0 {
+		return nil, fmt.Errorf("unreadable Greenhouse round record %s", path)
+	}
+	return &pending, nil
+}
+
+func worktreeHead(ctx context.Context, worktree string) (string, error) {
+	output, err := exec.CommandContext(ctx, "git", "-C", worktree, "rev-parse", "HEAD").Output()
+	if err != nil {
+		return "", fmt.Errorf("read the head of %s: %w", worktree, err)
+	}
+	return strings.TrimSpace(string(output)), nil
+}
diff --git a/internal/store/greenhouse_verdicts.go b/internal/store/greenhouse_verdicts.go
new file mode 100644
index 0000000..bbf3863
--- /dev/null
+++ b/internal/store/greenhouse_verdicts.go
@@ -0,0 +1,82 @@
+package store
+
+import (
+	"context"
+	"database/sql"
+	"encoding/json"
+	"errors"
+	"fmt"
+	"time"
+)
+
+const GreenhouseReviewProvider = "greenhouse"
+
+// ErrVerdictHeadMoved refuses a Verdict whose reviewed head is no longer the
+// Member's head when Posse records it.
+var ErrVerdictHeadMoved = errors.New("the reviewed head is no longer the Task head")
+
+type greenhouseReviewProvider struct{}
+
+func (greenhouseReviewProvider) RecordVerdict(ctx context.Context, tx VerdictTx, verdict Verdict) error {
+	if verdict.Provider != GreenhouseReviewProvider {
+		return sql.ErrNoRows
+	}
+	return insertVerdict(ctx, tx, verdict)
+}
+
+// RecordGreenhouseVerdict inserts a Greenhouse Verdict once per grant. It reads
+// the Member head inside the write transaction and refuses the insert when the
+// head differs from the reviewed one; it does not rely on Greenhouse's
+// `current` flag. It reports false when the grant already has a Verdict.
+func (db *DB) RecordGreenhouseVerdict(ctx context.Context, verdict Verdict, currentHead func(context.Context) (string, error)) (bool, error) {
+	if verdict.Grant == "" {
+		return false, errors.New("a Greenhouse Verdict needs its grant")
+	}
+	tx, err := db.beginTxWithRetry(ctx)
+	if err != nil {
+		return false, err
+	}
+	defer tx.Rollback()
+	var exists bool
+	if err := tx.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM verdicts WHERE grant_id=?)`, verdict.Grant).Scan(&exists); err != nil {
+		return false, err
+	}
+	if exists {
+		return false, nil
+	}
+	head, err := currentHead(ctx)
+	if err != nil {
+		return false, err
+	}
+	if head != verdict.Head {
+		return false, fmt.Errorf("%w: reviewed %s, now %s", ErrVerdictHeadMoved, verdict.Head, head)
+	}
+	if err := (greenhouseReviewProvider{}).RecordVerdict(ctx, tx, verdict); err != nil {
+		return false, err
+	}
+	return true, tx.Commit()
+}
+
+// CreateGreenhouseRecoveryNoticeOnce raises one Notice per parked Greenhouse
+// recovery of a Task Member.
+func (db *DB) CreateGreenhouseRecoveryNoticeOnce(ctx context.Context, projectID, taskID int64, repository, recoveryID, summary string) (bool, error) {
+	data, err := json.Marshal(struct {
+		Repository string `json:"repo"`
+		Recovery   string `json:"recovery_id"`
+	}{repository, recoveryID})
+	if err != nil {
+		return false, err
+	}
+	result, err := db.ExecContext(ctx, `INSERT INTO notices(project_id, task_id, kind, summary, data_json, created_at)
+		SELECT ?, ?, 'greenhouse_recovery_required', ?, ?, ?
+		WHERE NOT EXISTS (SELECT 1 FROM notices WHERE task_id=? AND kind='greenhouse_recovery_required' AND data_json=?)`,
+		projectID, taskID, summary, string(data), time.Now().UnixMilli(), taskID, string(data))
+	if err != nil {
+		return false, err
+	}
+	rows, err := result.RowsAffected()
+	if err != nil || rows == 0 {
+		return false, err
+	}
+	return true, db.PersistProject(ctx, projectID)
+}
