33: // greenhouseReview requests one Greenhouse Verdict for the exact head of a
34: // Change Task Member and records it as a parallel-mode Verdict. Only the Lead
35: // side calls it; no gate reads Greenhouse Verdicts yet.
36: func (s *Service) greenhouseReview(ctx *axi.Context, args []string) error {
37: 	parsed, err := parseArgs("_greenhouse review", args, map[string]flagSpec{"repo": {}, "rule": {repeatable: true}, "reviewer-backend": {}, "reviewer-model": {}, "timeout": {}})
38: 	if err != nil {
39: 		return err
40: 	}
41: 	if len(parsed.Positionals) != 1 {
42: 		return axi.Usage("_greenhouse review requires one Task id")
43: 	}
44: 	wait := 30 * time.Minute
45: 	if value := parsed.Flags["timeout"]; value != "" {
46: 		millis, err := strconv.Atoi(value)
47: 		if err != nil || millis < 1 {
48: 			return axi.Usage("--timeout takes a positive number of milliseconds")
49: 		}
50: 		wait = time.Duration(millis) * time.Millisecond
51: 	}
52: 	db, home, err := s.openDB()
53: 	if err != nil {
54: 		return err
55: 	}
56: 	defer db.Close()
57: 	project, err := s.projectForCWD(ctx.Context, db)
58: 	if err != nil {
59: 		return err
60: 	}
61: 	if err := s.requireLead(ctx.Context, db, project); err != nil {
62: 		return err
63: 	}
64: 	if s.workerCaller(ctx.Context, home) {
65: 		return axi.Failure("lead_only", "a Worker never calls Greenhouse", false, "Run this from the Project Lead pane")
66: 	}
67: 	if project.IsDirectory() {
68: 		return executionUnavailable(project)
69: 	}
70: 	task, err := s.currentTask(ctx.Context, db, project, parsed.Positionals[0])
71: 	if err != nil {
72: 		return err
73: 	}
74: 	if task.Type != "change" {
75: 		return axi.Failure("greenhouse_target_invalid", "Greenhouse reviews Change Tasks only", false)
76: 	}
77: 	member, err := greenhouseTaskMember(ctx.Context, db, project, task, parsed.Flags["repo"])
78: 	if err != nil {
79: 		return err
80: 	}
81: 	plan, err := task.AdmittedPlan()
82: 	if err != nil {
83: 		return admittedPlanFailure(err)
84: 	}
85: 	target, err := greenhouseTarget(ctx.Context, member)
86: 	if err != nil {
87: 		return err
88: 	}
89: 	binary, err := exec.LookPath("greenhouse")
90: 	if err != nil {
91: 		return axi.Failure("greenhouse_missing", "greenhouse is not installed on PATH", false, "Install Greenhouse, then retry")
92: 	}
93: 	tasks, err := posseTasks(ctx.Context, db)
94: 	if err != nil {
95: 		return err
96: 	}
97: 	daemon := &greenhouse.Daemon{Binary: binary, Home: greenhouse.HomeFor(home), Env: os.Environ(), InTask: func(pid int) bool {
98: 		for _, task := range tasks {
99: 			if processInTaskContainment(pid, task) {
100: 				return true
101: 			}
102: 		}
103: 		return false
104: 	}}
105: 	hostID := project.Name + "/" + taskIDString(task.Seq) + "/" + member.name
106: 	roundDir := filepath.Join(home, "projects", project.Name, "tasks", taskIDString(task.Seq), "greenhouse")
107: 	if err := os.MkdirAll(roundDir, 0o700); err != nil {
108: 		return err
109: 	}
110: 	round := greenhouse.Round{
111: 		Worktree: member.worktree, Host: greenhouse.Host{Name: "posse", ID: hostID}, GrantPrefix: hostID,
112: 		Intent: greenhouseIntent(task, plan), Target: target,
113: 		Settings: greenhouse.Settings{Rules: parsed.Repeated["rule"], ReviewerBackend: parsed.Flags["reviewer-backend"], ReviewerModel: parsed.Flags["reviewer-model"]},
114: 		Pending:  filepath.Join(roundDir, member.name+".pending.json"), Wait: wait,
115: 		Checkpoint: func(step string) { crashIntentAt("greenhouse-review", "after", step) },
116: 	}
117: 	blockAt := "P1"
118: 	if plan != nil && plan.ValidationLoops != nil && plan.ValidationLoops.Review.BlockAt != "" {
119: 		blockAt = plan.ValidationLoops.Review.BlockAt
120: 	}
121: 	var refused []axi.Object
122: 	for range greenhouseStaleRounds {
123: 		result, err := daemon.Review(ctx.Context, round)
124: 		var protocolErr *greenhouse.ProtocolError
125: 		if errors.As(err, &protocolErr) {
126: 			return axi.Failure("greenhouse_protocol", protocolErr.Error(), false, "No Verdict was requested")
127: 		}
128: 		if err != nil {
129: 			return axi.Failure("greenhouse_failed", err.Error(), true)
130: 		}
131: 		output := axi.Object{{Key: "task", Value: taskIDString(task.Seq)}, {Key: "repo", Value: member.name}, {Key: "outcome", Value: string(result.Outcome)}, {Key: "grant", Value: result.Grant}}
132: 		switch result.Outcome {
133: 		case greenhouse.Settled:
134: 			crashIntentAt("greenhouse-review", "after", "settled")
135: 			recorded, verdict, err := recordGreenhouseVerdict(ctx.Context, db, task, member, roundDir, blockAt, result)
136: 			if errors.Is(err, store.ErrVerdictHeadMoved) {
137: 				refused = append(refused, axi.Object{{Key: "grant", Value: result.Grant}, {Key: "reason", Value: err.Error()}})
138: 				if err := greenhouse.ClearPending(round.Pending); err != nil {
139: 					return err
140: 				}
141: 				continue
142: 			}
143: 			if err != nil {
144: 				return err
145: 			}
146: 			if err := greenhouse.ClearPending(round.Pending); err != nil {
147: 				return err
148: 			}
149: 			output = append(output, axi.Field{Key: "head", Value: verdict.Head}, axi.Field{Key: "verdict", Value: verdict.Outcome},
150: 				axi.Field{Key: "blocking", Value: verdict.Blocking}, axi.Field{Key: "findings", Value: verdict.FindingsPath}, axi.Field{Key: "recorded", Value: recorded}, axi.Field{Key: "replayed", Value: result.Replayed})
151: 		case greenhouse.Stale:
152: 			refused = append(refused, axi.Object{{Key: "grant", Value: result.Grant}, {Key: "reason", Value: "the head moved during the review"}})
153: 			if err := greenhouse.ClearPending(round.Pending); err != nil {
154: 				return err
155: 			}
156: 			continue
157: 		case greenhouse.RecoveryRequired:
158: 			summary := fmt.Sprintf("%s: Greenhouse review %s of %s parked after an interruption (%s); Posse issues no new grant until it recovers", taskIDString(task.Seq), result.Grant, member.name, result.Recovery.Reason)
159: 			if _, err := db.CreateGreenhouseRecoveryNoticeOnce(ctx.Context, project.ID, task.ID, member.name, result.Recovery.ID, summary); err != nil {
160: 				return err
161: 			}
162: 			output = append(output, axi.Field{Key: "recovery", Value: result.Recovery.ID})
163: 		}
164: 		if len(refused) > 0 {
165: 			output = append(output, axi.Field{Key: "refused", Value: refused})
166: 		}
167: 		return ctx.Print(output)
168: 	}
169: 	return ctx.Print(axi.Object{{Key: "task", Value: taskIDString(task.Seq)}, {Key: "repo", Value: member.name}, {Key: "outcome", Value: string(greenhouse.Stale)}, {Key: "refused", Value: refused}})
170: }
