132: func (d *Daemon) start(ctx context.Context) (int, error) {
133: 	log, err := os.OpenFile(filepath.Join(d.Home, logFile), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600)
134: 	if err != nil {
135: 		return 0, err
136: 	}
137: 	defer log.Close()
138: 	command := exec.Command(d.Binary, "daemon")
139: 	command.Dir = d.Home
140: 	command.Env = d.environment()
141: 	command.Stdout, command.Stderr = log, log
142: 	command.SysProcAttr = &syscall.SysProcAttr{Setsid: true}
143: 	if err := command.Start(); err != nil {
144: 		return 0, fmt.Errorf("start Greenhouse daemon: %w", err)
145: 	}
146: 	exited := make(chan error, 1)
147: 	go func() { exited <- command.Wait() }()
148: 	deadline := time.NewTimer(10 * time.Second)
149: 	defer deadline.Stop()
150: 	ticker := time.NewTicker(20 * time.Millisecond)
151: 	defer ticker.Stop()
152: 	for {
153: 		if pid, live := d.livePID(); live {
154: 			return pid, nil
155: 		}
156: 		select {
157: 		case <-ctx.Done():
158: 			return 0, ctx.Err()
159: 		case <-deadline.C:
160: 			return 0, fmt.Errorf("the Greenhouse daemon did not open its socket within 10s; see %s", filepath.Join(d.Home, logFile))
161: 		case err := <-exited:
162: 			// A concurrent start may own the home; its socket appears shortly.
163: 			if pid, live := d.waitLive(2 * time.Second); live {
164: 				return pid, nil
165: 			}
166: 			return 0, fmt.Errorf("the Greenhouse daemon exited before serving: %v; see %s", err, filepath.Join(d.Home, logFile))
167: 		case <-ticker.C:
168: 		}
169: 	}
170: }
171: 
172: func (d *Daemon) waitLive(limit time.Duration) (int, bool) {
173: 	for deadline := time.Now().Add(limit); time.Now().Before(deadline); time.Sleep(20 * time.Millisecond) {
174: 		if pid, live := d.livePID(); live {
175: 			return pid, true
176: 		}
177: 	}
178: 	return 0, false
179: }
180: 
181: // probe reads the daemon's protocol range with a request outside every range,
182: // which a daemon refuses without changing anything. A daemon that answers
183: // without a protocol block predates negotiation and speaks only version 1.
184: func (d *Daemon) probe(ctx context.Context) (Range, error) {
185: 	v, err := d.axi(ctx, d.Home, []byte(`{"version":999,"op":"inspect"}`))
186: 	if err != nil {
187: 		return Range{}, err
188: 	}
189: 	if v.Protocol == nil {
190: 		return Range{Min: 1, Max: 1}, nil
191: 	}
192: 	return *v.Protocol, nil
193: }
194: 
195: // refuseTaskCaller keeps Greenhouse out of every Task: a daemon started from a
196: // Task process would join its cgroup and carry its marker, and that Task's
197: // Teardown would stop reviews of other Tasks.
198: func (d *Daemon) refuseTaskCaller() error {
199: 	if os.Getenv("POSSE_TASK_ID") != "" || d.InTask(os.Getpid()) {
200: 		return errors.New("a Task process never calls Greenhouse; run this from the Project Lead pane")
201: 	}
202: 	return nil
203: }
204: 
205: func (d *Daemon) verifyPlacement(pid int) error {
206: 	if d.InTask(pid) {
207: 		return fmt.Errorf("the Greenhouse daemon %d runs inside a Posse Task", pid)
208: 	}
209: 	environ, err := os.ReadFile(filepath.Join("/proc", strconv.Itoa(pid), "environ"))
210: 	if err != nil {
211: 		return nil
212: 	}
213: 	for entry := range strings.SplitSeq(string(environ), "\x00") {
214: 		if strings.HasPrefix(entry, "POSSE_TASK_ID=") {
215: 			return fmt.Errorf("the Greenhouse daemon %d carries a Task marker", pid)
216: 		}
217: 	}
218: 	return nil
219: }
