63: 	data, err := json.Marshal(struct {
64: 		Repository string `json:"repo"`
65: 		Recovery   string `json:"recovery_id"`
66: 	}{repository, recoveryID})
67: 	if err != nil {
68: 		return false, err
69: 	}
70: 	result, err := db.ExecContext(ctx, `INSERT INTO notices(project_id, task_id, kind, summary, data_json, created_at)
71: 		SELECT ?, ?, 'greenhouse_recovery_required', ?, ?, ?
72: 		WHERE NOT EXISTS (SELECT 1 FROM notices WHERE task_id=? AND kind='greenhouse_recovery_required' AND data_json=?)`,
73: 		projectID, taskID, summary, string(data), time.Now().UnixMilli(), taskID, string(data))
74: 	if err != nil {
75: 		return false, err
76: 	}
77: 	rows, err := result.RowsAffected()
78: 	if err != nil || rows == 0 {
79: 		return false, err
80: 	}
