268: func greenhouseTarget(ctx context.Context, member greenhouseMember) (string, error) {
269: 	ref := "refs/heads/" + member.targetBranch
270: 	if _, err := gitOutput(ctx, member.root, "remote", "get-url", "origin"); err == nil {
271: 		ref = "refs/remotes/origin/" + member.targetBranch
272: 		if _, err := gitFetch(ctx, member.root, "origin", member.targetBranch+":"+ref); err != nil {
273: 			return "", axi.Failure("greenhouse_target_unavailable", "could not fetch target origin/"+member.targetBranch, true, err.Error())
274: 		}
275: 	}
276: 	commit, err := gitOutput(ctx, member.root, "rev-parse", "--verify", ref+"^{commit}")
277: 	if err != nil {
278: 		return "", axi.Failure("greenhouse_target_unavailable", "cannot resolve target "+member.targetBranch+" of "+member.name, false, err.Error())
279: 	}
280: 	return commit, nil
281: }
