12: const GreenhouseReviewProvider = "greenhouse"
13: 
14: // ErrVerdictHeadMoved refuses a Verdict whose reviewed head is no longer the
15: // Member's head when Posse records it.
16: var ErrVerdictHeadMoved = errors.New("the reviewed head is no longer the Task head")
17: 
18: type greenhouseReviewProvider struct{}
19: 
20: func (greenhouseReviewProvider) RecordVerdict(ctx context.Context, tx VerdictTx, verdict Verdict) error {
21: 	if verdict.Provider != GreenhouseReviewProvider {
22: 		return sql.ErrNoRows
23: 	}
24: 	return insertVerdict(ctx, tx, verdict)
25: }
26: 
27: // RecordGreenhouseVerdict inserts a Greenhouse Verdict once per grant. It reads
28: // the Member head inside the write transaction and refuses the insert when the
29: // head differs from the reviewed one; it does not rely on Greenhouse's
30: // `current` flag. It reports false when the grant already has a Verdict.
31: func (db *DB) RecordGreenhouseVerdict(ctx context.Context, verdict Verdict, currentHead func(context.Context) (string, error)) (bool, error) {
32: 	if verdict.Grant == "" {
33: 		return false, errors.New("a Greenhouse Verdict needs its grant")
34: 	}
35: 	tx, err := db.beginTxWithRetry(ctx)
36: 	if err != nil {
37: 		return false, err
38: 	}
39: 	defer tx.Rollback()
40: 	var exists bool
41: 	if err := tx.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM verdicts WHERE grant_id=?)`, verdict.Grant).Scan(&exists); err != nil {
42: 		return false, err
43: 	}
44: 	if exists {
45: 		return false, nil
46: 	}
47: 	head, err := currentHead(ctx)
48: 	if err != nil {
49: 		return false, err
50: 	}
51: 	if head != verdict.Head {
52: 		return false, fmt.Errorf("%w: reviewed %s, now %s", ErrVerdictHeadMoved, verdict.Head, head)
53: 	}
54: 	if err := (greenhouseReviewProvider{}).RecordVerdict(ctx, tx, verdict); err != nil {
55: 		return false, err
56: 	}
57: 	return true, tx.Commit()
58: }
59: 
60: // CreateGreenhouseRecoveryNoticeOnce raises one Notice per parked Greenhouse
61: // recovery of a Task Member.
62: func (db *DB) CreateGreenhouseRecoveryNoticeOnce(ctx context.Context, projectID, taskID int64, repository, recoveryID, summary string) (bool, error) {
63: 	data, err := json.Marshal(struct {
64: 		Repository string `json:"repo"`
65: 		Recovery   string `json:"recovery_id"`
66: 	}{repository, recoveryID})
67: 	if err != nil {
68: 		return false, err
69: 	}
70: 	result, err := db.ExecContext(ctx, `INSERT INTO notices(project_id, task_id, kind, summary, data_json, created_at)
71: 		SELECT ?, ?, 'greenhouse_recovery_required', ?, ?, ?
72: 		WHERE NOT EXISTS (SELECT 1 FROM notices WHERE task_id=? AND kind='greenhouse_recovery_required' AND data_json=?)`,
73: 		projectID, taskID, summary, string(data), time.Now().UnixMilli(), taskID, string(data))
74: 	if err != nil {
75: 		return false, err
76: 	}
77: 	rows, err := result.RowsAffected()
78: 	if err != nil || rows == 0 {
79: 		return false, err
80: 	}
81: 	return true, db.PersistProject(ctx, projectID)
82: }
