74: 	}
75: 	_, err := tx.ExecContext(ctx, `INSERT INTO verdicts(task_id,repo,provider,protocol,grant_id,head_sha,target_sha,review_base_sha,verdict,blocking,rules_digest,config_digest,input_digest,backend,model,findings_digest,findings_path,mode,recorded_at) VALUES(?,?,?,?,NULLIF(?,''),?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
76: 		verdict.TaskID, verdict.Repository, verdict.Provider, verdict.Protocol, verdict.Grant,
77: 		verdict.Head, verdict.Target, verdict.ReviewBase, verdict.Outcome, verdict.Blocking,
78: 		verdict.RulesDigest, verdict.ConfigDigest, verdict.InputDigest, verdict.Backend, verdict.Model,
79: 		verdict.FindingsHash, verdict.FindingsPath, verdict.Mode, verdict.RecordedAt)
